import{z as o,x as s,o as t,c as p,q as r,j as i,D as e,d as l,s as n,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"策略容量与拥挤","description":"","frontmatter":{"title":"策略容量与拥挤","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/strategy-capacity.md","filePath":"quant/strategy-capacity.md","lastUpdated":1791063341000}'),d={name:"quant/strategy-capacity.md"};function m(h,a,u,D,q,C){const A=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="策略容量与拥挤" tabindex="-1">策略容量与拥挤 <a class="header-anchor" href="#策略容量与拥挤" aria-label="Permalink to &quot;策略容量与拥挤&quot;">​</a></h1><div class="epigraph"><p>容量不是一个使夏普降到零的魔法金额。它是给定持有期与参与率时，额外资金开始改写你自己赖以存在的价格与拥挤状态的那条曲线。</p><footer>—— 据 Pástor, Stambaugh and Taylor 对技能与规模的讨论；对照 Stein 对同质套利者制造不稳定的论述</footer></div><p><a href="/quant/holding-horizon">持有期与换手</a>钉死了策略时钟 \\(H\\) 和它该付的那一截摩擦。本课的缺口是规模：同样的 \\(H\\)，10 个亿与 10 个万面对的冲击、借券和拥挤不是线性外推。Pástor、Stambaugh 与 Taylor 把基金规模与技能的递减写进资产定价；执行文献用参与率把规模映射到冲击。拥挤是别人的规模叠在同一信号上。后课延迟预算假定容量讨论已经把「不能靠更快吃薄深度」的那部分分开。本课不重写 <a href="/quant/kyle-model">Kyle</a> 的均衡推导，只借用「流量移动价格」这一句。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纸面权重 \\(w\\) 乘 AUM 得到股数 \\(q\\)。\\(q\\) 相对 ADV、相对可见深度、相对可借券，决定你是价格接受者还是价格的一部分。容量问题是：在目标 \\(H\\) 下，把 AUM 从 \\(K\\) 增到 \\(K&#39;\\)，净期望如何掉。掉的通道至少三条。冲击：参与率上升，永久冲击吃掉 alpha。可交易宇宙：小名字先触达手数与深度上限，组合被迫滑向大盘，风格漂移。拥挤：其他资金读到同一公开信号，你的 \\(q\\) 只是总量 \\(Q\\) 的一小截，价格已经被 \\(Q\\) 移动。只做自己的参与率应力测试，会高估容量。</p><p><span class="marginnote">数字实例：目标买入 2 亿元，标的日均成交 20 亿元。分 5 天建仓，日参与率约 \\(2\\text{亿}/(5\\times 20\\text{亿})=2\\%\\)；一天打完则参与率 10%，按平方根律冲击约放大约 2.2 倍。同样的钱，建仓节奏直接改写容量。</span></p><p>拥挤与容量不是同义词。容量可以在你独享信号时仍受深度限制；拥挤可以在你规模很小时已把 alpha 压光。问题是同时估计「自己的弹性」和「看不见的 \\(Q\\)」。</p><h3 id="参与率是桥梁-不是容量本身" tabindex="-1">参与率是桥梁，不是容量本身 <a class="header-anchor" href="#参与率是桥梁-不是容量本身" aria-label="Permalink to &quot;参与率是桥梁，不是容量本身&quot;">​</a></h3><p>日参与率 \\(q/(H\\cdot \\mathrm{ADV})\\) 把规模变成执行参数。同一 AUM，拉长 \\(H\\) 可以降低参与率，这是上一课的交点。容量曲线应在固定 \\(H\\) 上画，再在另一张图上允许 \\(H\\) 调整。把「我们把再平衡从日改成周，容量变大」写成能力，其实是改了产品。Novy-Marx–Velikov 已经说明低换手更容易活过成本；那是 \\(H\\) 的选择，不是无限 AUM。</p><p><span class="marginnote">用全样本 ADV 当分母会高估压力期容量。ADV 在你正要退出时下降，正是流动性螺旋的入口。压力 ADV 应单独成列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>构造容量曲线：在回测里把目标名义按比例放大，用带永久冲击的成交模型重算净收益，直到净夏普或净 IR 降到预设门槛。冲击模型至少随参与率上升，禁止用常数滑点——常数会让容量看起来无限，直到你任意设定的滑点把 alpha 吃完。报告风格漂移：放大后的加权平均市值、有效股票数。借券约束对空头单独画一条曲线。</p><p>拥挤代理：信号的横截面离散度、实现换手相对历史、因子 ETF 与期货持仓、借券费率。这些是公开可观测的拥挤，不是别人的机密 AUM。Stein 指出同质化套利本身是不稳定来源；拥挤指标变极端时，应把容量门槛下调，而不是仍用平静期曲线。附录里还有更专门的容量衰减课，本课只把曲线与拥挤状态写成制度。</p><h3 id="自己的冲击与共同冲击" tabindex="-1">自己的冲击与共同冲击 <a class="header-anchor" href="#自己的冲击与共同冲击" aria-label="Permalink to &quot;自己的冲击与共同冲击&quot;">​</a></h3><p>校准若只用自己的历史成交，估计的是「在当时拥挤水平上再加一点」的局部弹性，不是「全市场跟你一起翻倍」的弹性。压力情景应把共同流量 \\(Q\\) 放大，而不是只放大自己的 \\(q\\)。这与 <a href="/quant/kyle-lambda">Kyle</a> 经验回归的精神一致：\\(\\Delta p\\) 对总带符号流量，不是对你的账号流量。把账号级 TCA 的 lambda 当策略容量，会把别人已经造成的价格当成你可以再走一次的空间。</p><p><span class="marginnote">术语翻译：TCA（交易成本分析）就是「给自己的成交记账」——用你的成交价对比决策时点的中点，量出每一单自己推了多少价。注意账号级 TCA 的 lambda 只反映「你单子的边际冲击」，不含别人同向流量的推力。</span></p>',16)),(t(),i(B,null,{default:e(()=>[n(A,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20S0%5B%22%E5%9B%BA%E5%AE%9A%E6%8C%81%E6%9C%89%E6%9C%9F%20H%22%5D%20--%3E%20S1%5B%22%E6%8C%89%E6%AF%94%E4%BE%8B%E6%94%BE%E5%A4%A7%E5%90%8D%E4%B9%89%20q%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E7%94%A8%E9%9A%8F%E5%8F%82%E4%B8%8E%E7%8E%87%E4%B8%8A%E5%8D%87%E7%9A%84%E5%86%B2%E5%87%BB%E6%A8%A1%E5%9E%8B%E9%87%8D%E7%AE%97%22%5D%0A%20%20S2%20--%3E%20Q1%7B%22%E5%87%80%20IR%20%E4%BB%8D%E9%AB%98%E4%BA%8E%E9%97%A8%E6%A7%9B%22%7D%0A%20%20Q1%20--%20%22%E6%98%AF%22%20--%3E%20S1%0A%20%20Q1%20--%20%22%E5%90%A6%22%20--%3E%20S3%5B%22%E8%AE%B0%E5%BD%95%E8%BF%87%E9%9B%B6%E4%B8%8E%E9%97%A8%E6%A7%9B%E8%A7%84%E6%A8%A1%22%5D%0A%20%20S3%20--%3E%20S4%5B%22%E6%8A%A5%E5%91%8A%E5%B8%82%E5%80%BC%E6%BC%82%E7%A7%BB%E4%B8%8E%E6%9C%89%E6%95%88%20N%22%5D%0A%20%20S4%20--%3E%20S5%5B%22%E7%A9%BA%E5%A4%B4%E6%8C%89%E5%80%9F%E5%88%B8%E7%BA%A6%E6%9D%9F%E5%8D%95%E7%8B%AC%E7%94%BB%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20S5%20--%3E%20S6%5B%22%E6%8B%A5%E6%8C%A4%E6%9E%81%E7%AB%AF%E6%97%B6%E4%B8%8B%E8%B0%83%E9%97%A8%E6%A7%9B%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"规模通过永久冲击改写未来可交易的 alpha：你今天买，明天的开仓价已经含你的 \\(\\Lambda q\\)。拥挤通过同一通道，只是 \\(q\\) 换成 \\(Q\\)。可交易宇宙收缩使策略暴露滑向市场因子，毛 alpha 的风格纯度下降，即使冲击模型显示「还能做」。三条机制在不同 AUM 上轮流成为紧约束：小规模时紧的是换手与价差（上一课），中等规模时紧的是冲击与借券，大规模时紧的是拥挤与风格漂移。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：容量像卡车换挡——低速挡（小规模）费在换手与价差，中速挡费在冲击与借券，高速挡费在拥挤与风格漂移。哪个挡位先「响」取决于你开到多快（规模），不能拿一挡的噪音判断整车极限。")],-1)),a[6]||(a[6]=E("p",null,"做市类策略的容量是存货风险与逆向选择，不是 ADV 的某一百分比；把 POV 容量公式套到做市上，对象错了。本课默认对象是有方向、有再平衡的组合策略。",-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"不要把容量报成单一美元数。报曲线：在若干 AUM 上的净 IR、参与率、有效 N。单一数字一定对应某个未声明的门槛与某个未声明的冲击函数。")],-1)),(t(),i(B,null,{default:e(()=>[n(A,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TB%0A%20%20H%5B%22%E7%BB%99%E5%AE%9A%E6%8C%81%E6%9C%89%E6%9C%9F%20H%22%5D%20--%3E%20Q%5B%22%E7%9B%AE%E6%A0%87%E8%A7%84%E6%A8%A1%20q%22%5D%0A%20%20Q%20--%3E%20P%5B%22%E5%8F%82%E4%B8%8E%E7%8E%87%20vs%20ADV%20%2F%20%E6%B7%B1%E5%BA%A6%22%5D%0A%20%20P%20--%3E%20I%5B%22%E6%B0%B8%E4%B9%85%E5%86%B2%E5%87%BB%E5%90%83%20alpha%22%5D%0A%20%20Q%20--%3E%20U%5B%22%E5%AE%87%E5%AE%99%E6%BB%91%E5%90%91%E5%A4%A7%E7%9B%98%22%5D%0A%20%20C%5B%22%E4%BB%96%E4%BA%BA%E5%85%B1%E5%90%8C%E6%B5%81%E9%87%8F%20Q%22%5D%20--%3E%20I%0A%20%20I%20--%3E%20CAP%5B%22%E5%AE%B9%E9%87%8F%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20U%20--%3E%20CAP%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<h3 id="做市容量不是-adv-的百分比" tabindex="-1">做市容量不是 ADV 的百分比 <a class="header-anchor" href="#做市容量不是-adv-的百分比" aria-label="Permalink to &quot;做市容量不是 ADV 的百分比&quot;">​</a></h3><p>方向性组合用参与率桥接到冲击；做市的紧约束是存货方差与毒性。把 POV 公式套到做市，会在窄价差名字上高估可挂规模。产品类型要先分类再画曲线。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>另类数据与私人订单流的容量，受数据许可和覆盖率约束，ADV 不是紧的。债券 OTC 的容量是询价网络与存货，见后课，不要用股票 ADV。本课不写如何把单子拆到别人看不见以「扩大容量」的手法。下一课在给定规模与 \\(H\\) 上分配延迟：不是所有策略都需要抢 tick。</p><p><span class="marginnote">另类数据策略的容量往往先碰到覆盖与许可，而不是 ADV。那条曲线应另画，不要和股票冲击曲线叠成一个美元数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>容量是固定 \\(H\\) 上净表现相对 AUM 的曲线，外加拥挤状态。</li><li>参与率连接规模与冲击；拉长 \\(H\\) 是改产品，不是提高能力。</li><li>局部 TCA lambda 低估共同流量放大时的冲击。</li><li>紧约束从价差换手，转到冲击借券，再转到拥挤与风格漂移。</li><li>只报一个美元容量而不报门槛与冲击函数，没有信息。</li><li>出处：Pástor, Stambaugh and Taylor, <em>JFE</em>, 2015；Stein, <em>JFE</em>, 2009；冲击与参与率见 Almgren–Chriss 传统与 Novy-Marx–Velikov 的成本后异常。</li></ul>',7))])}const S=o(d,[["render",m]]);export{c as __pageData,S as default};
